function expandGroup(title,expanded=true,persist=true){const nav=document.getElementById('nav');if(!nav)return;for(const group of nav.querySelectorAll('details[data-nav-group]')){const open=expanded&&group.dataset.navGroup===title&&!group.hidden;if(group.open!==open)group.open=open;group.querySelector('summary')?.setAttribute('aria-expanded',String(open))}if(persist)saveNavigation({openGroup:expanded?title:null})}
